Definition mem_ok (M : word -> option byte) : Prop :=
  PMK.ek L LB S 14336 [(o, 24)] M0 M /\ PMK.dk L LB S 14336 M0 M /\ L5C.stk (hl_sptop L) M S 14336 /\ L5.defined M o 24.

